export const attachDocuments = (
  movementId: MaybeRefOrGetter<string>,
  documentUploadForm?: MaybeRefOrGetter<DocumentUploadForm>,
  options?: SecondParameter<typeof apiRequest>,
  signal?: AbortSignal,
) => {
  movementId = toValue(movementId)
  documentUploadForm = toValue(documentUploadForm)
  const formData = new FormData()
  if (documentUploadForm?.files !== undefined) {
    documentUploadForm?.files.forEach((value) => formData.append(`files`, value))
  }

  return apiRequest<DocumentView[]>(
    {
      url: `/api/material-movements/${movementId}/documents`,
      method: 'POST',
      headers: { 'Content-Type': 'multipart/form-data' },
      data: formData,
      signal,
    },
    options,
  )
}

